INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(94386, 'ruRU', 'Невозможно! Это ничего не значит. Так или иначе, этот мир сгорит!', '', 24330),
(94387, 'ruRU', 'Потушите эти огни, пока не вернулся Натанос! Не хочу стать едой для его псов.', '', 24330),
(94388, 'ruRU', 'Быстрее! Спустите этот корабль на воду, пока нас не заметило ещё больше этих мерзких крабовых падальщиков.', '', 24330),
(94389, 'ruRU', 'Молоты в руки, глупцы! У нас расписание.', '', 24330),
(94390, 'ruRU', 'Вы позволите Альянсу потопить ваш корабль? Докажите слабость их оружия, спустив эту баржу на воду.', '', 24330),
(94391, 'ruRU', 'Натанос поручил нам вернуть его корабль в рабочее состояние.$b$bНо эти ленивые дурни возятся целую вечность... погоди... ты это слышишь?', '', 24330),
(94392, 'ruRU', 'Что слышу?', '', 24330),
(94393, 'ruRU', 'Летит!', '', 24330),
(94394, 'ruRU', 'И не лезь больше, крабомордая мразь!', '', 24330),
(94406, 'ruRU', 'Полировка', '', 24330),
(94408, 'ruRU', '|cFFFF0000%s|r защищает своего хозяина |cFFFF0000|Hspell:180040|h[Оберегом владыки]|h|r!', '', 24330),
(94410, 'ruRU', 'Аватара |cFFFF0000%s|r вступает в бой!', '', 24330),
(94412, 'ruRU', '|TINTERFACE\\ICONS\\ACHIEVEMENT_CHARACTER_HUMAN_MALE.BLP:40|tЯ уже вижу, что это нужно предварительно закалить. Нагрей руду в горне.', '', 24330),
(94413, 'ruRU', '|TINTERFACE\\ICONS\\ACHIEVEMENT_CHARACTER_HUMAN_MALE.BLP:40|tТеперь, быстро, закали её в корыте.', '', 24330),
(94414, 'ruRU', '|TINTERFACE\\ICONS\\ACHIEVEMENT_CHARACTER_HUMAN_MALE.BLP:40|tВидишь? Уже выглядит лучше. Нагрей и закали снова.', '', 24330),
(94415, 'ruRU', '|TINTERFACE\\ICONS\\ACHIEVEMENT_CHARACTER_HUMAN_MALE.BLP:40|tТеперь доведи металл в горне до температуры вытяжки.', '', 24330),
(94416, 'ruRU', '|TINTERFACE\\ICONS\\ACHIEVEMENT_CHARACTER_HUMAN_MALE.BLP:40|tЭтого должно хватить. Теперь вытянем металл в брусок.', '', 24330),
(94417, 'ruRU', '|TINTERFACE\\ICONS\\ACHIEVEMENT_CHARACTER_HUMAN_MALE.BLP:40|tТы знаешь, что делать дальше. Нагрей брусок, затем отбей молотом нужную форму.', '', 24330),
(94418, 'ruRU', '|TINTERFACE\\ICONS\\ACHIEVEMENT_CHARACTER_HUMAN_MALE.BLP:40|tОчень хорошо. Приготовимся к сварке. Нанеси немного флюса с моего верстака.', '', 24330),
(94419, 'ruRU', 'Герои, быстрее! Нельзя допустить, чтобы Ироксус вошёл в Жестокий Пир!', '', 24330),
(94420, 'ruRU', 'Я прибыл, молокососы. Выходите сразиться со мной, и покончим с этим!', '', 24330),
(94421, 'ruRU', 'Хе-хе, превосходно, превосходно.', '', 24330),
(94422, 'ruRU', 'Впечатляюще.', '', 24330),
(94424, 'ruRU', 'Всё лежит на твоих плечах, командир. Построй нам флот, чтобы мы могли атаковать Гулдана со всех сторон. Удачи!', '', 24330),
(94425, 'ruRU', 'Этим достойным мужчинам и женщинам нужен лидер, $p. Твои деяния доказывают, что именно ты — очевидный выбор, чтобы нести эту ношу. Идём, я обращусь к ним от твоего имени.', '', 24330),
(94426, 'ruRU', 'Паладины Азерота, вы собрались, чтобы оплакать потерю Верховного лорда Тириона Фордринга. Многие из вас видели в нём идеал, образец того, к чему все мы стремимся.', '', 24330),
(94427, 'ruRU', 'Вам всем известны благородные деяния защитника рядом со мной. $p избран Светом, чтобы стать преемником Тириона на посту Верховного лорда. Под началом нашего нового лидера этот орден станет могучим оружием против Легиона!', '', 24330),
(94428, 'ruRU', 'В этот день Орден Серебряной Длани возрождается! Вместе мы заставим содрогнуться от нашей мощи самого Саргераса!', '', 24330),
(94429, 'ruRU', '|TINTERFACE\\ICONS\\ACHIEVEMENT_CHARACTER_HUMAN_MALE.BLP:40|tЛадно. Похоже, лей-камень бурно реагирует с флюсом. Остановимся прямо тут.', '', 24330),
(94430, 'ruRU', 'Мы ищем Солога Роарка!', '', 24330),
(94431, 'ruRU', 'Нет, друг. У нас общий враг, и нам нужны твои навыки.', '', 24330);
